type User = { id: string; role: string; status: string; name: string; email: string }
type ApiResult = { user?: User; csrfToken?: string; status?: string; error?: string; fields?: Array<{ field: string; message: string }>; [key: string]: unknown }
type AdminSummary = { users?: Record<string, string | number>; partners?: Record<string, string | number> }

const csrfKey = 'doc_motor_csrf'
const saveCsrf = (value?: string) => { if (value) sessionStorage.setItem(csrfKey, value) }
const csrf = () => sessionStorage.getItem(csrfKey) || ''

async function api<T extends ApiResult = ApiResult>(path: string, options: RequestInit = {}): Promise<T> {
  const headers = new Headers(options.headers)
  headers.set('Content-Type', 'application/json')
  const token = csrf()
  if (token) headers.set('X-CSRF-Token', token)
  const response = await fetch(path, { ...options, headers, credentials: 'include' })
  const body = response.status === 204 ? {} : await response.json().catch(() => ({}))
  if (!response.ok) { const message = friendlyApiDetails(body.error, body.details) || friendlyValidationMessages(body.fields) || friendlyApiMessage(body.error, response.status); const error = new Error(message) as Error & { code?: string; details?: unknown }; error.code = String(body.error || ''); error.details = body.details || body.fields; throw error }
  saveCsrf(body.csrfToken)
  return body as T
}

function Shell({ children, showBrand = true }: { children: ReactNode; showBrand?: boolean }) {
  return <main className="auth-shell">{showBrand && <a className="auth-brand" href="/"><BrandLogo /></a>}{children}<p className="auth-footnote">Doc Motor · Documentação Veicular</p></main>
}

function Field({ label, name, type = 'text', required = true, value, onChange }: { label: string; name: string; type?: string; required?: boolean; value: string; onChange: (value: string) => void }) {
  const [visible, setVisible] = useState(false); const isPassword = type === 'password'; const inputType = isPassword && visible ? 'text' : type
  return <label className="auth-field"><span>{label}</span><span className="auth-input-wrap"><input name={name} type={inputType} autoComplete={isPassword ? name.toLowerCase().includes('current') ? 'current-password' : 'new-password' : name === 'email' ? 'email' : undefined} required={required} value={value} onChange={(event) => onChange(event.target.value)} />{isPassword && <button className="password-toggle" type="button" onClick={() => setVisible((current) => !current)} aria-label={visible ? 'Ocultar senha' : 'Mostrar senha'}>{visible ? 'Ocultar' : 'Mostrar'}</button>}</span></label>
}

function PasswordHint({ role }: { role: 'CLIENT' | 'PARTNER' | 'ADMINISTRATOR' | 'RESET' }) { const text = role === 'CLIENT' ? 'Use pelo menos 6 caracteres. Números são permitidos, exceto combinações muito comuns.' : role === 'PARTNER' ? 'Use pelo menos 8 caracteres. Números são permitidos, exceto combinações muito comuns.' : role === 'ADMINISTRATOR' ? 'Use pelo menos 12 caracteres, com letra maiúscula, minúscula e número.' : 'A senha deve atender à política do perfil da conta.'; return <p className="password-policy-hint">{text}</p> }

function Message({ error }: { error: string }) { return error ? <p className="auth-error" role="alert">{error}</p> : null }

export function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' }); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); try { const result = await api('/api/auth/login', { method: 'POST', body: JSON.stringify(form) }); saveCsrf(result.csrfToken); const next = new URLSearchParams(window.location.search).get('next'); const safeNext = next?.startsWith('/') ? next : null; const target = result.user?.status === 'PENDING' ? '/aguardando-aprovacao' : safeNext || (result.user?.role === 'ADMINISTRATOR' ? '/admin' : result.user?.role === 'PARTNER' ? '/parceiro' : '/cliente'); window.location.assign(target) } catch (err) { setError(err instanceof Error ? err.message : 'Falha ao entrar.') } }
  return <Shell><section className="auth-card"><p className="auth-kicker">ÁREA RESTRITA</p><h1>Entrar na plataforma</h1><p className="auth-muted">Acesse seu painel Doc Motor.</p><form onSubmit={submit}><Field label="E-mail" name="email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} /><Field label="Senha" name="password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} /><Message error={error} /><button className="auth-button" type="submit">Entrar</button></form><div className="auth-links"><a href="/cadastro-parceiro">Quero ser parceiro</a><a href="/cadastro-cliente">Criar conta de cliente</a><a href="/recuperar-senha">Esqueci minha senha</a></div></section></Shell>
}

export function ClientRegistrationPage() {
  const [form, setForm] = useState({ name: '', email: '', cpf: '', whatsapp: '', password: '', passwordConfirmation: '', acceptTerms: false, privacyAcknowledgement: false }); const [error, setError] = useState('')
  const set = (key: string, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }))
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); try { await api('/api/auth/register/client', { method: 'POST', body: JSON.stringify(form) }); window.location.assign('/cliente') } catch (err) { setError(err instanceof Error ? err.message : 'Falha no cadastro.') } }
  return <Shell><section className="auth-card auth-card-wide"><p className="auth-kicker">NOVO CLIENTE</p><h1>Crie sua conta</h1><p className="auth-muted">Use dados verdadeiros para que o atendimento documental seja seguro.</p><form onSubmit={submit} className="auth-grid"><Field label="Nome completo" name="name" value={form.name} onChange={(value) => set('name', value)} /><Field label="CPF" name="cpf" value={form.cpf} onChange={(value) => set('cpf', value)} /><Field label="WhatsApp" name="whatsapp" value={form.whatsapp} onChange={(value) => set('whatsapp', value)} /><Field label="E-mail" name="email" type="email" value={form.email} onChange={(value) => set('email', value)} /><div className="password-block"><PasswordHint role="CLIENT" /><Field label="Senha" name="password" type="password" value={form.password} onChange={(value) => set('password', value)} /><Field label="Confirme a senha" name="passwordConfirmation" type="password" value={form.passwordConfirmation} onChange={(value) => set('passwordConfirmation', value)} /></div><Consent form={form} set={set} /><Message error={error} /><button className="auth-button" type="submit">Criar conta</button></form><a className="auth-back" href="/login">Já tenho uma conta</a></section></Shell>
}

function Consent({ form, set }: { form: { acceptTerms: boolean; privacyAcknowledgement: boolean }; set: (key: string, value: boolean) => void }) { return <div className="auth-consent"><label><input type="checkbox" checked={form.acceptTerms} onChange={(event) => set('acceptTerms', event.target.checked)} required /> Aceito os termos de uso.</label><label><input type="checkbox" checked={form.privacyAcknowledgement} onChange={(event) => set('privacyAcknowledgement', event.target.checked)} required /> Estou ciente da política de privacidade.</label></div> }

export function PartnerRegistrationPage() {
  const [form, setForm] = useState({ email: '', whatsapp: '', password: '', passwordConfirmation: '', legalName: '', tradeName: '', cpfCnpj: '', responsibleName: '', zipCode: '', address: '', addressNumber: '', complement: '', neighborhood: '', city: '', state: '', segment: 'Desmanche', acceptTerms: false, privacyAcknowledgement: false }); const [error, setError] = useState('')
  const set = (key: string, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }))
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); const type = documentTypeFor(form.cpfCnpj); if (!type || (type === 'PF' && form.cpfCnpj.replace(/\D/g, '').length !== 11) || (type === 'PJ' && form.cpfCnpj.replace(/[^0-9A-Z]/gi, '').length !== 14)) { setError(type === 'PF' ? 'O CPF está incompleto. Confira os números digitados.' : 'Informe um CPF ou CNPJ completo.'); return } try { const result = await api('/api/auth/register/partner', { method: 'POST', body: JSON.stringify({ ...form, personType: type, cpfCnpj: form.cpfCnpj }) }); saveCsrf(result.csrfToken); window.location.assign('/aguardando-aprovacao') } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível concluir o cadastro. Tente novamente.') } }
  return <Shell><section className="auth-card auth-card-wide"><p className="auth-kicker">SEJA PARCEIRO</p><h1>Cadastre seu interesse</h1><p className="auth-muted">A conta ficará pendente de aprovação administrativa antes do acesso operacional.</p><form onSubmit={submit} className="auth-grid"><div className="form-section-title">Identificação do parceiro</div><Field label="Nome ou razão social" name="legalName" value={form.legalName} onChange={(value) => set('legalName', value)} /><Field label="Nome fantasia" name="tradeName" required={false} value={form.tradeName} onChange={(value) => set('tradeName', value)} /><Field label="CPF ou CNPJ" name="cpfCnpj" value={form.cpfCnpj} onChange={(value) => set('cpfCnpj', formatCpfCnpj(value))} /><p className="document-type-hint">{documentTypeFor(form.cpfCnpj) === 'PJ' ? 'Pessoa jurídica identificada pelo CNPJ.' : documentTypeFor(form.cpfCnpj) === 'PF' && form.cpfCnpj.replace(/\D/g, '').length === 11 ? 'Pessoa física identificada pelo CPF.' : 'Digite o CPF ou CNPJ; o tipo será identificado automaticamente.'}</p><div className="form-section-title">Dados do responsável</div><Field label="Nome completo do responsável" name="responsibleName" value={form.responsibleName} onChange={(value) => set('responsibleName', value)} /><div className="form-section-title">Contato e endereço</div><Field label="E-mail" name="email" type="email" value={form.email} onChange={(value) => set('email', value)} /><Field label="WhatsApp" name="whatsapp" value={form.whatsapp} onChange={(value) => set('whatsapp', formatPhone(value))} /><Field label="CEP" name="zipCode" required={false} value={form.zipCode} onChange={(value) => set('zipCode', formatCep(value))} /><Field label="Endereço" name="address" required={false} value={form.address} onChange={(value) => set('address', value)} /><Field label="Número" name="addressNumber" required={false} value={form.addressNumber} onChange={(value) => set('addressNumber', value)} /><Field label="Complemento" name="complement" required={false} value={form.complement} onChange={(value) => set('complement', value)} /><Field label="Bairro" name="neighborhood" required={false} value={form.neighborhood} onChange={(value) => set('neighborhood', value)} /><Field label="Cidade" name="city" required={false} value={form.city} onChange={(value) => set('city', value)} /><Field label="Estado (UF)" name="state" value={form.state} onChange={(value) => set('state', value.toUpperCase())} /><SelectField label="Segmento" value={form.segment} options={['Desmanche', 'Revenda de motores', 'Autopeças', 'Oficina mecânica', 'Centro automotivo', 'Revenda de veículos', 'Prestador de serviços', 'Outros']} onChange={(value) => set('segment', value)} /><div className="form-section-title">Dados de acesso</div><p className="auth-muted form-section-copy">O acesso será feito pelo e-mail informado acima.</p><div className="password-block"><PasswordHint role="PARTNER" /><Field label="Senha" name="password" type="password" value={form.password} onChange={(value) => set('password', value)} /><Field label="Confirme a senha" name="passwordConfirmation" type="password" value={form.passwordConfirmation} onChange={(value) => set('passwordConfirmation', value)} /></div><Consent form={form} set={set} /><Message error={error} /><button className="auth-button" type="submit">Enviar cadastro</button></form><a className="auth-back" href="/login">Voltar para entrar</a></section></Shell>
}

function SelectField({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="auth-field"><span>{label}</span><select value={value} onChange={(event) => onChange(event.target.value)}>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select></label> }

export function PasswordRecoveryPage() {
  const [email, setEmail] = useState(''); const [sent, setSent] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); try { await api('/api/auth/forgot-password', { method: 'POST', body: JSON.stringify({ email }) }); setSent(true) } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível solicitar a recuperação.') } }
  return <Shell><section className="auth-card"><p className="auth-kicker">SEGURANÇA</p><h1>Recuperar senha</h1>{sent ? <p className="auth-muted">Se existir uma conta para este e-mail, enviaremos as instruções de redefinição.</p> : <form onSubmit={submit}><Field label="E-mail" name="email" type="email" value={email} onChange={setEmail} /><Message error={error} /><button className="auth-button" type="submit">Enviar instruções</button></form>}<a className="auth-back" href="/login">Voltar para entrar</a></section></Shell>
}

export function ResetPasswordPage() {
  const token = new URLSearchParams(window.location.search).get('token') || ''; const [form, setForm] = useState({ password: '', passwordConfirmation: '' }); const [done, setDone] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); try { await api('/api/auth/reset-password', { method: 'POST', body: JSON.stringify({ token, ...form }) }); setDone(true) } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível redefinir a senha.') } }
  return <Shell><section className="auth-card"><p className="auth-kicker">SEGURANÇA</p><h1>Nova senha</h1>{done ? <><p className="auth-muted">Senha alterada com sucesso.</p><a className="auth-button auth-button-link" href="/login">Entrar</a></> : <form onSubmit={submit}><PasswordHint role="RESET" /><Field label="Nova senha" name="password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} /><Field label="Confirme a senha" name="passwordConfirmation" type="password" value={form.passwordConfirmation} onChange={(value) => setForm({ ...form, passwordConfirmation: value })} /><Message error={error} /><button className="auth-button" type="submit">Alterar senha</button></form>}</section></Shell>
}

type PartnerStatus = { id: string; legal_name: string; trade_name?: string | null; status: string; segment?: string | null; city?: string | null; state?: string | null; created_at: string; rejection_reason?: string | null }

export function PartnerStatusPage() {
  const [company, setCompany] = useState<PartnerStatus | null>(null); const [error, setError] = useState('')
  useEffect(() => { api('/api/partner/status').then((result) => setCompany((result as ApiResult & { company?: PartnerStatus }).company || null)).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível consultar o cadastro.')) }, [])
  if (error) return <Shell><section className="auth-card"><p className="auth-kicker">ÁREA DO PARCEIRO</p><h1>Acompanhe seu cadastro</h1><p className="auth-muted">Entre com a conta usada no cadastro para consultar o status da solicitação.</p><Message error={error === 'AUTHENTICATION_REQUIRED' ? '' : error} /><a className="auth-button auth-button-link" href="/login?next=%2Farea-do-parceiro">Entrar</a></section></Shell>
  if (!company) return <Shell><section className="auth-card"><p className="auth-muted">Carregando o status do cadastro…</p></section></Shell>
  return <Shell><section className="auth-card"><p className="auth-kicker">ÁREA DO PARCEIRO</p><h1>{company.status === 'PENDING' ? 'Cadastro recebido.' : 'Status da parceria'}</h1><p className="auth-muted">{company.status === 'PENDING' ? 'Sua solicitação está aguardando análise administrativa. Você poderá acessar os recursos operacionais após a aprovação.' : company.status === 'REJECTED' ? 'A solicitação não foi aprovada. Entre em contato pelo WhatsApp para receber orientação.' : 'Consulte abaixo as informações da sua parceria.'}</p><div className="dashboard-notice"><strong>{company.trade_name || company.legal_name}</strong><br />Status: {translateStatus(company.status)}<br />Solicitação: {new Date(company.created_at).toLocaleDateString('pt-BR')}{company.segment ? <><br />Segmento: {company.segment}</> : null}{company.city || company.state ? <><br />Localidade: {company.city || '—'}/{company.state || '—'}</> : null}{company.rejection_reason ? <><br />Motivo informado: {company.rejection_reason}</> : null}</div><a className="auth-button auth-button-link" href="https://wa.me/5515997118125">Falar com atendimento</a><LogoutButton /></section></Shell>
}

export function PartnerAreaPage() {
  const [loading, setLoading] = useState(true)
  useEffect(() => { api('/api/auth/me').then((result) => { const user = result.user; if (!user) return window.location.assign('/login?next=%2Farea-do-parceiro'); if (user.role === 'ADMINISTRATOR') return window.location.assign('/admin'); if (user.role !== 'PARTNER') return window.location.assign('/acesso-nao-autorizado'); if (user.status === 'PENDING') return window.location.assign('/aguardando-aprovacao'); if (user.status === 'ACTIVE') return window.location.assign('/parceiro'); return window.location.assign('/acesso-nao-autorizado') }).catch(() => window.location.assign('/login?next=%2Farea-do-parceiro')).finally(() => setLoading(false)) }, [])
  return <Shell><section className="auth-card"><p className="auth-muted">{loading ? 'Verificando seu acesso…' : 'Redirecionando…'}</p></section></Shell>
}

export function StatusPage({ title, text, href = '/' }: { title: string; text: string; href?: string }) { return <Shell><section className="auth-card"><p className="auth-kicker">DOC MOTOR</p><h1>{title}</h1><p className="auth-muted">{text}</p><a className="auth-button auth-button-link" href={href}>Continuar</a></section></Shell> }

function LogoutButton() { const logout = async () => { await api('/api/auth/logout', { method: 'POST' }).catch(() => undefined); sessionStorage.removeItem(csrfKey); window.location.assign('/login') }; return <button className="auth-button auth-secondary" onClick={logout}>Sair</button> }

function translateStatus(status?: string) { return ({ ACTIVE: 'Ativo', PENDING: 'Aguardando aprovação', SUSPENDED: 'Suspenso', REJECTED: 'Recusado' } as Record<string, string>)[status || ''] || status || '—' }

function ChangePasswordForm({ role }: { role: string }) { const [form, setForm] = useState({ currentPassword: '', newPassword: '', newPasswordConfirmation: '' }); const [message, setMessage] = useState(''); const submit = async (event: FormEvent) => { event.preventDefault(); setMessage(''); try { await api('/api/auth/change-password', { method: 'POST', body: JSON.stringify(form) }); setForm({ currentPassword: '', newPassword: '', newPasswordConfirmation: '' }); setMessage('Senha alterada. As outras sessões foram encerradas.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível alterar a senha.') } }; const policyRole = role === 'ADMINISTRATOR' ? 'ADMINISTRATOR' : role === 'PARTNER' ? 'PARTNER' : 'CLIENT'; return <details className="password-change"><summary>Alterar minha senha</summary><form onSubmit={submit}><PasswordHint role={policyRole} /><Field label="Senha atual" name="currentPassword" type="password" value={form.currentPassword} onChange={(value) => setForm({ ...form, currentPassword: value })} /><Field label="Nova senha" name="newPassword" type="password" value={form.newPassword} onChange={(value) => setForm({ ...form, newPassword: value })} /><Field label="Confirme a nova senha" name="newPasswordConfirmation" type="password" value={form.newPasswordConfirmation} onChange={(value) => setForm({ ...form, newPasswordConfirmation: value })} /><button className="auth-button" type="submit">Salvar nova senha</button>{message && <p className="auth-muted">{message}</p>}</form></details> }

function NavItem({ href, label, icon: Icon, disabled = false }: { href?: string; label: string; icon: LucideIcon; disabled?: boolean }) { const active = href && window.location.pathname === href; return disabled ? <span className="nav-disabled nav-item" title={label}><Icon size={15} aria-hidden="true" /><span>{label}<small>Em breve</small></span></span> : <a className="nav-item" href={href} title={label} aria-current={active ? 'page' : undefined}><Icon size={16} aria-hidden="true" /><span>{label}</span></a> }
function AdminNavigation() { return <nav className="admin-navigation" aria-label="Navegação administrativa"><span className="nav-group-label">GESTÃO</span><NavItem href="/admin" label="Visão geral" icon={LayoutDashboard} /><NavItem href="/admin/parceiros" label="Parceiros" icon={BriefcaseBusiness} /><NavItem href="/admin/clientes" label="Clientes" icon={Users} /><NavItem href="/admin/servicos-solicitados" label="Serviços solicitados" icon={ClipboardList} /><span className="nav-group-label">SERVIÇOS</span><NavItem href="/admin/servicos/regularizacao-motor" label="Regularização de motor" icon={CarFront} /><NavItem href="/admin/servicos/suspensao" label="Regularizar suspensão" icon={Wrench} /><NavItem href="/admin/servicos/outras-modificacoes" label="Outras modificações" icon={Cog} /><NavItem href="/admin/servicos/emissor-crlv" label="Emissor de CRLV" icon={FileText} /><NavItem href="/admin/servicos/consultas" label="Consultas" icon={Search} /><span className="nav-group-label">CONFIGURAÇÕES</span><NavItem href="/admin/configuracao-servicos" label="Configuração de serviços" icon={Settings2} /><NavItem href="/admin/catalogo-modificacoes" label="Catálogo de modificações" icon={Cog} /><NavItem href="/admin/comissoes" label="Comissões" icon={BriefcaseBusiness} /><NavItem href="/admin/chaves-api" label="Chaves de API" icon={KeyRound} /><NavItem href="/admin/configuracoes" label="Configurações gerais" icon={Settings2} /><span className="nav-group-label">CONTA</span><NavItem href="/admin/minha-conta" label="Minha conta" icon={UserRound} /></nav> }
function PartnerNavigation() { return <nav className="admin-navigation" aria-label="Navegação do parceiro"><span className="nav-group-label">GESTÃO</span><NavItem href="/parceiro" label="Visão geral" icon={LayoutDashboard} /><NavItem label="Meus orçamentos" icon={ClipboardList} disabled /><NavItem label="Meus serviços" icon={BriefcaseBusiness} disabled /><span className="nav-group-label">SERVIÇOS</span><NavItem href="/parceiro/servicos/regularizacao-motor" label="Regularização de motor" icon={CarFront} /><NavItem href="/parceiro/servicos/suspensao" label="Regularizar suspensão" icon={Wrench} /><NavItem href="/parceiro/servicos/outras-modificacoes" label="Outras modificações" icon={Cog} /><NavItem href="/parceiro/servicos/emissor-crlv" label="Emissor de CRLV" icon={FileText} /><NavItem href="/parceiro/servicos/consultas" label="Consultas" icon={Search} /><span className="nav-group-label">CONTA</span><NavItem href="/parceiro/minha-conta" label="Minha conta" icon={UserRound} /></nav> }
function DashboardFrame({ user, title, children }: { user: User; title: string; children: ReactNode }) { const [menuOpen, setMenuOpen] = useState(false); const [collapsed, setCollapsed] = useState(() => localStorage.getItem('docmotor.sidebar.collapsed') === 'true'); useEffect(() => { localStorage.setItem('docmotor.sidebar.collapsed', String(collapsed)) }, [collapsed]); return <main className="app-shell"><section className={`dashboard-layout${collapsed ? ' sidebar-collapsed' : ''}`}><aside className={`dashboard-sidebar${menuOpen ? ' is-open' : ''}`} id="dashboard-navigation"><div className="sidebar-brand"><BrandLogo /><p className="sidebar-caption">DOC MOTOR</p></div>{user.role === 'ADMINISTRATOR' ? <AdminNavigation /> : user.role === 'PARTNER' ? <PartnerNavigation /> : null}<a className="commercial-link" href="/">Site comercial</a><LogoutButton /></aside><div className="dashboard-main"><header className="dashboard-topbar"><button className="mobile-menu-toggle" type="button" aria-expanded={menuOpen} aria-controls="dashboard-navigation" onClick={() => setMenuOpen((current) => !current)}>{menuOpen ? 'Fechar menu' : 'Abrir menu'}</button><button className="sidebar-collapse-toggle" type="button" onClick={() => setCollapsed((current) => !current)} aria-label={collapsed ? 'Expandir menu lateral' : 'Recolher menu lateral'}>{collapsed ? '»' : '«'}</button><span className="dashboard-user">{user.name}</span><span className="dashboard-role">{user.role === 'ADMINISTRATOR' ? 'Administrador' : user.role === 'PARTNER' ? 'Parceiro' : 'Cliente'}</span></header><div className="dashboard-content"><div className="page-heading"><p className="auth-kicker">{title}</p><h1>{title[0] + title.slice(1).toLowerCase()}</h1></div>{children}</div></div></section></main> }

type BuilderItem = Record<string, string | number | boolean | null | undefined>
type BuilderEditor = { version: BuilderItem; sections: BuilderItem[]; fields: BuilderItem[]; options: BuilderItem[]; billingItems: BuilderItem[]; rules: BuilderItem[]; documents: BuilderItem[]; messages: BuilderItem[]; queries: BuilderItem[]; validationErrors: string[] }

function ServiceBuilder() {
  const [services, setServices] = useState<BuilderItem[]>([]); const [selected, setSelected] = useState(''); const [editor, setEditor] = useState<BuilderEditor | null>(null); const [settings, setSettings] = useState({ name: '', slug: '', category: '', availabilityMode: 'ALL', availableToClient: true, availableToPartner: true, displayOrder: 0 }); const [tab, setTab] = useState('form'); const [error, setError] = useState(''); const [simulationError, setSimulationError] = useState(''); const [notice, setNotice] = useState(''); const [newService, setNewService] = useState({ code: '', name: '', slug: '', category: 'Documentação veicular' }); const [newField, setNewField] = useState({ fieldKey: '', label: '', fieldType: 'TEXT', sectionId: '', conditionField: '', conditionOperator: 'EQUALS', conditionValue: '', calculationOperation: 'ADD', calculationOperandA: '', calculationOperandB: '' }); const [newSection, setNewSection] = useState({ stableKey: '', label: '' }); const [newDocument, setNewDocument] = useState({ documentCode: '', name: '', requirementType: 'OPTIONAL' }); const [newQuery, setNewQuery] = useState({ sourceId: '', queryKey: '', label: '', contextKey: 'vehicle_target', plateFieldKey: '' }); const [newMessage, setNewMessage] = useState({ messageKey: '', severity: 'INFO', content: '' }); const [option, setOption] = useState({ fieldId: '', optionValue: '', optionLabel: '' }); const [billingMode, setBillingMode] = useState('REQUIRED'); const [billingCondition, setBillingCondition] = useState({ field: '', value: '' }); const [mapping, setMapping] = useState({ queryId: '', targetFieldKey: '', normalizedPath: '' }); const [action, setAction] = useState({ ruleId: '', actionType: 'MANUAL_REVIEW', targetKey: '' }); const [dataSources, setDataSources] = useState<BuilderItem[]>([]); const [billingCatalog, setBillingCatalog] = useState<BuilderItem[]>([]); const [billingId, setBillingId] = useState(''); const [rule, setRule] = useState({ name: '', field: '', operator: 'EQUALS', value: '', expectedResult: 'MANUAL_REVIEW' }); const [answers, setAnswers] = useState<Record<string, unknown>>({}); const [simulation, setSimulation] = useState<Record<string, unknown> | null>(null); const [validationIssues, setValidationIssues] = useState<ValidationIssue[]>([])
  const manualContactState = useState<Record<string, unknown> | null>(null); const manualContact = manualContactState[0]; const setManualContact = manualContactState[1]
  const loadServices = () => api<{ items?: BuilderItem[] }>('/api/admin/services').then((result) => setServices(result.items || [])).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar os serviços.'))
  const loadEditor = (serviceId: string) => { setSelected(serviceId); return api<BuilderEditor & ApiResult>(`/api/admin/services/${serviceId}/editor`).then((result) => { setEditor(result); setSettings({ name: String(result.version.service_name || ''), slug: String(result.version.slug || ''), category: String(result.version.category || ''), availabilityMode: String(result.version.availability_mode || 'ALL'), availableToClient: Boolean(result.version.available_to_client), availableToPartner: Boolean(result.version.available_to_partner), displayOrder: Number(result.version.display_order || 0) }) }).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar o editor.')) }
  useEffect(() => { void loadServices(); api<{ items?: BuilderItem[] }>('/api/admin/billing-items').then((result) => setBillingCatalog(result.items || [])).catch(() => undefined); api<{ items?: BuilderItem[] }>('/api/admin/data-sources').then((result) => setDataSources(result.items || [])).catch(() => undefined) }, []); useEffect(() => { if (simulationError) { setError(simulationError); setSimulation(null) } }, [simulationError]); useEffect(() => { const category = String(answers['vehicle_target.category'] || '').toUpperCase(); const mode = String(answers['engine.identification_mode'] || '').toUpperCase(); if (category !== 'MOTORCYCLE' && mode !== 'UNKNOWN' && mode !== 'MANUAL') return; setAnswers((current) => { const next = { ...current }; let changed = false; for (const key of Object.keys(next)) if ((category === 'MOTORCYCLE' || mode === 'UNKNOWN' || (mode === 'MANUAL' && key === 'vehicle_donor.plate')) && key.startsWith('vehicle_donor.')) { delete next[key]; changed = true } return changed ? next : current }) }, [answers['engine.identification_mode'], answers['vehicle_target.category']])
   useEffect(() => { if (manualContact) return; void api<{ settings?: Record<string, unknown> }>('/api/admin/settings').then((result) => setManualContact(result.settings || null)).catch(() => undefined) }, [manualContact])
   useEffect(() => { if (String(answers['vehicle_target.category'] || '').toUpperCase() !== 'MOTORCYCLE') return; setAnswers((current) => { if (!Object.prototype.hasOwnProperty.call(current, 'engine.identification_mode')) return current; const next = { ...current }; delete next['engine.identification_mode']; return next }) }, [answers['vehicle_target.category']])
   useEffect(() => { setEditor((current) => { if (!current) return current; const category = String(answers['vehicle_target.category'] || '').toUpperCase(); const mode = String(answers['engine.identification_mode'] || '').toUpperCase(); const fields = current.fields.map((field) => { const originalType = String(field.__originalFieldType || field.field_type || 'TEXT'); const key = String(field.field_key || ''); const condition = field.visibility_condition as Record<string, unknown> | null | undefined; const conditionVisible = !condition || evaluateDeclarativeCondition(condition, answers); const motorcycleOrigin = category === 'MOTORCYCLE' && (key.startsWith('vehicle_donor.') || key === 'engine.identification_mode'); const unknownOrigin = mode === 'UNKNOWN' && key.startsWith('vehicle_donor.'); const manualPlate = mode === 'MANUAL' && key === 'vehicle_donor.plate'; return { ...field, __originalFieldType: originalType, field_type: !conditionVisible || motorcycleOrigin || unknownOrigin || manualPlate ? 'CALCULATED' : originalType } }); return { ...current, fields } }) }, [answers, setEditor])
  const refresh = () => selected ? loadEditor(selected) : Promise.resolve()
  const saveService = async (event: FormEvent) => { event.preventDefault(); setError(''); try { const result = await api<{ serviceId?: string } & ApiResult>('/api/admin/services', { method: 'POST', body: JSON.stringify({ ...newService, serviceType: 'MAIN', availabilityMode: 'ALL', displayOrder: 0, availableToClient: true, availableToPartner: true }) }); setNotice('Serviço criado em rascunho.'); setNewService({ code: '', name: '', slug: '', category: 'Documentação veicular' }); await loadServices(); if (result.serviceId) await loadEditor(result.serviceId) } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível criar o serviço.') } }
  const addSection = async (event: FormEvent) => { event.preventDefault(); try { await api(`/api/admin/service-versions/${editor?.version.id}/sections`, { method: 'POST', body: JSON.stringify({ stableKey: newSection.stableKey, label: newSection.label, displayOrder: editor?.sections.length ? editor.sections.length * 10 : 10 }) }); setNewSection({ stableKey: '', label: '' }); setNotice('Seção adicionada.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar a seção.') } }
  const addField = async (event: FormEvent) => { event.preventDefault(); try { const calculation = newField.fieldType === 'CALCULATED' ? { operation: newField.calculationOperation, operands: [newField.calculationOperandA, newField.calculationOperandB].filter(Boolean).map((field) => ({ field })), decimals: 2 } : null; const visibilityCondition = newField.conditionField ? { all: [{ field: newField.conditionField, operator: newField.conditionOperator, value: newField.conditionValue }] } : null; await api(`/api/admin/service-versions/${editor?.version.id}/fields`, { method: 'POST', body: JSON.stringify({ ...newField, sectionId: newField.sectionId || null, calculation, visibilityCondition, isRequired: false, isEditable: true, dataOrigin: newField.fieldType === 'CALCULATED' ? 'CALCULATED' : 'MANUAL', displayOrder: editor?.fields.length ? editor.fields.length * 10 : 10 }) }); setNewField({ fieldKey: '', label: '', fieldType: 'TEXT', sectionId: '', conditionField: '', conditionOperator: 'EQUALS', conditionValue: '', calculationOperation: 'ADD', calculationOperandA: '', calculationOperandB: '' }); setNotice('Campo adicionado ao formulário.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar o campo.') } }
  const addBilling = async () => { if (!billingId || !editor) return; try { const conditionExpression = billingMode === 'CONDITIONAL' && billingCondition.field ? { all: [{ field: billingCondition.field, operator: 'EQUALS', value: billingCondition.value }] } : null; await api(`/api/admin/service-versions/${editor.version.id}/billing-items`, { method: 'POST', body: JSON.stringify({ billingItemId: billingId, billingMode, conditionExpression, quantity: 1, displayOrder: editor.billingItems.length * 10 }) }); setNotice('Item vinculado à versão.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível vincular a cobrança.') } }
  const addOption = async (event: FormEvent) => { event.preventDefault(); try { await api(`/api/admin/fields/${option.fieldId}/options`, { method: 'POST', body: JSON.stringify({ optionValue: option.optionValue, optionLabel: option.optionLabel, displayOrder: editor?.options.length ? editor.options.length * 10 : 10 }) }); setOption({ fieldId: '', optionValue: '', optionLabel: '' }); setNotice('Opção adicionada ao campo.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar a opção.') } }; const addMapping = async (event: FormEvent) => { event.preventDefault(); try { await api(`/api/admin/queries/${mapping.queryId}/mappings`, { method: 'POST', body: JSON.stringify({ targetFieldKey: mapping.targetFieldKey, normalizedPath: mapping.normalizedPath, dataOrigin: 'EXTERNAL' }) }); setMapping({ queryId: '', targetFieldKey: '', normalizedPath: '' }); setNotice('Mapeamento adicionado.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar o mapeamento.') } }; const addAction = async (event: FormEvent) => { event.preventDefault(); try { await api(`/api/admin/rules/${action.ruleId}/actions`, { method: 'POST', body: JSON.stringify({ actionType: action.actionType, targetKey: action.targetKey || null, payload: {}, displayOrder: 10 }) }); setAction({ ruleId: '', actionType: 'MANUAL_REVIEW', targetKey: '' }); setNotice('Ação adicionada à regra.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar a ação.') } }; const addRule = async (event: FormEvent) => { event.preventDefault(); if (!editor || !rule.field) return; try { await api('/api/admin/rules', { method: 'POST', body: JSON.stringify({ serviceId: editor.version.service_id, serviceVersionId: editor.version.id, name: rule.name, conditions: { all: [{ field: rule.field, operator: rule.operator, value: rule.value }] }, technicalLimits: {}, expectedResult: rule.expectedResult, status: 'DRAFT', priority: editor.rules.length * 10 + 10 }) }); setNotice('Regra criada como rascunho.'); setRule({ name: '', field: '', operator: 'EQUALS', value: '', expectedResult: 'MANUAL_REVIEW' }); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível criar a regra.') } }
  const addDocument = async (event: FormEvent) => { event.preventDefault(); if (!editor) return; try { await api(`/api/admin/service-versions/${editor.version.id}/documents`, { method: 'POST', body: JSON.stringify({ ...newDocument, displayOrder: editor.documents.length * 10 + 10 }) }); setNewDocument({ documentCode: '', name: '', requirementType: 'OPTIONAL' }); setNotice('Exigência documental adicionada.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar o documento.') } }
  const addQuery = async (event: FormEvent) => { event.preventDefault(); if (!editor) return; try { await api(`/api/admin/service-versions/${editor.version.id}/queries`, { method: 'POST', body: JSON.stringify({ ...newQuery, plateFieldKey: newQuery.plateFieldKey || null, isRequired: false, isEnabled: true }) }); setNewQuery({ sourceId: '', queryKey: '', label: '', contextKey: 'vehicle_target', plateFieldKey: '' }); setNotice('Consulta externa registrada como adaptador pendente.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível registrar a consulta.') } }
  const addMessage = async (event: FormEvent) => { event.preventDefault(); if (!editor) return; try { await api(`/api/admin/service-versions/${editor.version.id}/messages`, { method: 'POST', body: JSON.stringify({ ...newMessage, displayOrder: editor.messages.length * 10 + 10 }) }); setNewMessage({ messageKey: '', severity: 'INFO', content: '' }); setNotice('Mensagem configurável adicionada.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível adicionar a mensagem.') } }
  const saveSettings = async (event: FormEvent) => { event.preventDefault(); if (!editor) return; try { await api(`/api/admin/services/${editor.version.service_id}`, { method: 'PATCH', body: JSON.stringify(settings) }); setNotice('Configuração geral atualizada.'); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível atualizar a configuração.') } }; const changeVersionStatus = async (status: string) => { if (!editor) return; try { await api(`/api/admin/service-versions/${editor.version.id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); setNotice(`Versão ${status === 'PUBLISHED' ? 'publicada' : status === 'ARCHIVED' ? 'arquivada' : 'reaberta'} como rascunho.`); await refresh() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível alterar o status da versão.') } }; const simulate = async (event: FormEvent) => { event.preventDefault(); if (!editor) return; setSimulationError(''); setValidationIssues([]); try { const result = await api<{ result?: Record<string, unknown> } & ApiResult>(`/api/admin/service-versions/${editor.version.id}/simulate`, { method: 'POST', body: JSON.stringify({ answers }) }); setSimulation(result.result || null); setValidationIssues([]) } catch (err) { setSimulationError(err instanceof Error ? err.message : 'Não foi possível executar a simulação.'); setValidationIssues(normalizeValidationIssues((err as Error & { details?: unknown }).details, editor.fields as Array<Record<string, unknown>>)) } }
  const renderField = (field: BuilderItem) => shouldRenderServiceField(field, answers, (editor?.rules || []) as Array<Record<string, unknown>>) ? <ServiceFieldRenderer key={String(field.field_key)} field={field} options={(editor?.options || []).filter((option) => option.field_id === field.id)} catalog={[]} rules={(editor?.rules || []) as Array<Record<string, unknown>>} values={answers} error={validationIssues.find((issue) => issue.field === String(field.field_key))?.message} focusOnError={validationIssues[0]?.field === String(field.field_key)} onChange={(key, value) => { setAnswers((current) => ({ ...current, [key]: value })); setSimulation(null) }} /> : null
  return <section className="service-builder"><div className="builder-heading"><div><p className="auth-kicker">CONFIGURAÇÕES NO-CODE</p><h2>Construtor de serviços</h2><p className="auth-muted">Crie formulários, cobranças e regras sem editar código. Tudo começa como rascunho.</p></div><select value={selected} onChange={(event) => void loadEditor(event.target.value)}><option value="">Selecione um serviço</option>{services.map((service) => <option key={String(service.id)} value={String(service.id)}>{String(service.name)}</option>)}</select></div>{error && <Message error={error} />}{notice && <p className="builder-success" role="status">{notice}</p>}<form className="builder-create" onSubmit={saveService}><input aria-label="Código do serviço" placeholder="CÓDIGO_INTERNO" value={newService.code} onChange={(event) => setNewService({ ...newService, code: event.target.value.toUpperCase() })} required /><input aria-label="Nome do serviço" placeholder="Nome do novo serviço" value={newService.name} onChange={(event) => setNewService({ ...newService, name: event.target.value })} required /><input aria-label="Slug do serviço" placeholder="slug-amigavel" value={newService.slug} onChange={(event) => setNewService({ ...newService, slug: event.target.value })} required /><button className="auth-button" type="submit">Criar serviço</button></form>{editor && <><div className="builder-tabs">{[['settings', 'Configuração'], ['form', 'Formulário'], ['billing', 'Cobranças'], ['rules', 'Regras'], ['documents', 'Documentos'], ['external', 'Consultas externas'], ['messages', 'Mensagens'], ['simulate', 'Simulador']].map(([value, label]) => <button type="button" className={tab === value ? 'is-active' : ''} key={value} onClick={() => setTab(value)}>{label}</button>)}</div><div className="builder-panel"><p className="builder-version">{String(editor.version.service_name)} · versão {String(editor.version.version_number)} · {String(editor.version.status)}</p>{tab === 'settings' && <div><h3>Configuração geral e versão</h3><form className="builder-inline" onSubmit={saveSettings}><input placeholder="Nome do serviço" value={settings.name} onChange={(event) => setSettings({ ...settings, name: event.target.value })} required /><input placeholder="Slug" value={settings.slug} onChange={(event) => setSettings({ ...settings, slug: event.target.value })} required /><input placeholder="Categoria" value={settings.category} onChange={(event) => setSettings({ ...settings, category: event.target.value })} required /><select value={settings.availabilityMode} onChange={(event) => setSettings({ ...settings, availabilityMode: event.target.value })}><option value="ALL">Disponível em todas as condições</option><option value="CONFIGURED">Somente quando configurado</option></select><label><input type="checkbox" checked={settings.availableToClient} onChange={(event) => setSettings({ ...settings, availableToClient: event.target.checked })} /> Cliente</label><label><input type="checkbox" checked={settings.availableToPartner} onChange={(event) => setSettings({ ...settings, availableToPartner: event.target.checked })} /> Parceiro</label><button type="submit">Salvar configuração</button></form><div className="builder-inline"><strong>Status: {String(editor.version.status)}</strong><button type="button" onClick={() => void changeVersionStatus('DRAFT')}>Salvar como rascunho</button><button type="button" onClick={() => void changeVersionStatus('PUBLISHED')}>Publicar versão</button><button type="button" onClick={() => void changeVersionStatus('ARCHIVED')}>Arquivar versão</button></div><p className="auth-muted">A publicação só é permitida quando a configuração passa pela validação declarativa do backend.</p></div>}{tab === 'form' && <><div className="builder-columns"><div><h3>Seções</h3><form className="builder-inline" onSubmit={addSection}><input placeholder="Identificador da seção" value={newSection.stableKey} onChange={(event) => setNewSection({ ...newSection, stableKey: event.target.value })} required /><input placeholder="Nome da seção" value={newSection.label} onChange={(event) => setNewSection({ ...newSection, label: event.target.value })} required /><button type="submit">Adicionar</button></form>{editor.sections.map((section) => <div className="builder-row" key={String(section.id)}><strong>{String(section.label)}</strong><small>{String(section.stable_key)}</small></div>)}</div><div><h3>Campos</h3><form className="builder-inline" onSubmit={addField}><input placeholder="identificador.campo" value={newField.fieldKey} onChange={(event) => setNewField({ ...newField, fieldKey: event.target.value })} required /><input placeholder="Rótulo" value={newField.label} onChange={(event) => setNewField({ ...newField, label: event.target.value })} required /><select value={newField.fieldType} onChange={(event) => setNewField({ ...newField, fieldType: event.target.value })}>{['TEXT', 'LONG_TEXT', 'INTEGER', 'DECIMAL', 'MONEY', 'PERCENT', 'DATE', 'PHONE', 'EMAIL', 'CPF_CNPJ', 'VEHICLE_PLATE', 'SINGLE_SELECT', 'MULTI_SELECT', 'RADIO', 'CHECKBOX', 'YES_NO', 'CALCULATED', 'API_FIELD', 'INFO', 'DOCUMENT_REQUIREMENT'].map((type) => <option key={type}>{type}</option>)}</select><select value={newField.sectionId} onChange={(event) => setNewField({ ...newField, sectionId: event.target.value })}><option value="">Sem seção</option>{editor.sections.map((section) => <option key={String(section.id)} value={String(section.id)}>{String(section.label)}</option>)}</select>{newField.conditionField && <><select value={newField.conditionField} onChange={(event) => setNewField({ ...newField, conditionField: event.target.value })}><option value="">Campo condicional</option>{editor.fields.map((field) => <option key={String(field.id)} value={String(field.field_key)}>{String(field.label)}</option>)}</select><select value={newField.conditionOperator} onChange={(event) => setNewField({ ...newField, conditionOperator: event.target.value })}><option value="EQUALS">Igual a</option><option value="NOT_EQUALS">Diferente de</option><option value="FILLED">Preenchido</option></select><input placeholder="Valor condicional" value={newField.conditionValue} onChange={(event) => setNewField({ ...newField, conditionValue: event.target.value })} /></>}{newField.fieldType === "CALCULATED" && <><select value={newField.calculationOperation} onChange={(event) => setNewField({ ...newField, calculationOperation: event.target.value })}><option value="ADD">Somar</option><option value="SUBTRACT">Subtrair</option><option value="PERCENT_VARIATION">Variação percentual</option><option value="ROUND">Arredondar</option></select><select value={newField.calculationOperandA} onChange={(event) => setNewField({ ...newField, calculationOperandA: event.target.value })}><option value="">Primeiro campo</option>{editor.fields.map((field) => <option key={String(field.id)} value={String(field.field_key)}>{String(field.label)}</option>)}</select><select value={newField.calculationOperandB} onChange={(event) => setNewField({ ...newField, calculationOperandB: event.target.value })}><option value="">Segundo campo</option>{editor.fields.map((field) => <option key={String(field.id)} value={String(field.field_key)}>{String(field.label)}</option>)}</select></> }<button type="submit">Adicionar campo</button></form>{editor.fields.map((field) => <div className="builder-row" key={String(field.id)}><strong>{String(field.label)}</strong><small>{String(field.field_key)} · {String(field.field_type)}</small></div>)}<form className="builder-inline" onSubmit={addOption}><select value={option.fieldId} onChange={(event) => setOption({ ...option, fieldId: event.target.value })}><option value="">Campo com opções</option>{editor.fields.filter((field) => ['SINGLE_SELECT', 'RADIO', 'YES_NO'].includes(String(field.field_type))).map((field) => <option key={String(field.id)} value={String(field.id)}>{String(field.label)}</option>)}</select><input placeholder="Valor da opção" value={option.optionValue} onChange={(event) => setOption({ ...option, optionValue: event.target.value })} required /><input placeholder="Rótulo da opção" value={option.optionLabel} onChange={(event) => setOption({ ...option, optionLabel: event.target.value })} required /><button type="submit">Adicionar opção</button></form></div></div></>}{tab === 'billing' && <div><h3>Itens de cobrança</h3><div className="builder-inline"><select value={billingId} onChange={(event) => setBillingId(event.target.value)}><option value="">Selecionar item do catálogo</option>{billingCatalog.map((item) => <option key={String(item.id)} value={String(item.id)}>{String(item.name)} {item.default_amount_cents === null ? '(sob consulta)' : `R$ ${(Number(item.default_amount_cents) / 100).toFixed(2).replace('.', ',')}`}</option>)}</select><select value={billingMode} onChange={(event) => setBillingMode(event.target.value)}><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="CONDITIONAL">Condicional</option></select>{billingMode === "CONDITIONAL" && <><select value={billingCondition.field} onChange={(event) => setBillingCondition({ ...billingCondition, field: event.target.value })}><option value="">Campo da condição</option>{editor.fields.map((field) => <option key={String(field.id)} value={String(field.field_key)}>{String(field.label)}</option>)}</select><input placeholder="Valor da condição" value={billingCondition.value} onChange={(event) => setBillingCondition({ ...billingCondition, value: event.target.value })} /></>}<button type="button" onClick={() => void addBilling()}>Vincular item</button></div>{editor.billingItems.map((item) => <div className="builder-row" key={String(item.id)}><strong>{String(item.name)}</strong><small>{item.default_amount_cents === null ? 'Valor não definido' : `R$ ${(Number(item.default_amount_cents) / 100).toFixed(2).replace('.', ',')}`} · {String(item.billing_mode)}</small></div>)}</div>}{tab === 'rules' && <div><h3>Regras declarativas</h3><form className="builder-inline builder-rule" onSubmit={addRule}><input placeholder="Nome da regra" value={rule.name} onChange={(event) => setRule({ ...rule, name: event.target.value })} required /><select value={rule.field} onChange={(event) => setRule({ ...rule, field: event.target.value })}><option value="">Campo</option>{editor.fields.map((field) => <option key={String(field.id)} value={String(field.field_key)}>{String(field.label)}</option>)}</select><select value={rule.operator} onChange={(event) => setRule({ ...rule, operator: event.target.value })}>{['EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'LESS_THAN', 'GREATER_OR_EQUAL', 'LESS_OR_EQUAL', 'BETWEEN', 'CONTAINS', 'FILLED', 'EMPTY', 'TRUE', 'FALSE', 'IN_LIST'].map((operator) => <option key={operator}>{operator}</option>)}</select><input placeholder="Valor" value={rule.value} onChange={(event) => setRule({ ...rule, value: event.target.value })} /><select value={rule.expectedResult} onChange={(event) => setRule({ ...rule, expectedResult: event.target.value })}><option value="MANUAL_REVIEW">Análise manual</option><option value="VIABLE_WITH_REQUIREMENTS">Viável com exigências</option><option value="OUT_OF_CRITERIA">Fora dos critérios</option><option value="VIABLE">Potencialmente viável</option></select><button type="submit">Salvar rascunho</button></form>{editor.rules.map((item) => <div className="builder-row" key={String(item.id)}><strong>{String(item.name)}</strong><small>{String(item.expected_result)} · prioridade {String(item.priority)}</small></div>)}<form className="builder-inline" onSubmit={addAction}><select value={action.ruleId} onChange={(event) => setAction({ ...action, ruleId: event.target.value })}><option value="">Regra alvo</option>{editor.rules.map((item) => <option key={String(item.id)} value={String(item.id)}>{String(item.name)}</option>)}</select><select value={action.actionType} onChange={(event) => setAction({ ...action, actionType: event.target.value })}><option value="MANUAL_REVIEW">Análise manual</option><option value="BLOCK_AUTOMATED_QUOTE">Bloquear orçamento</option><option value="ADD_BILLING_ITEM">Adicionar cobrança</option><option value="REQUIRE_DOCUMENT">Exigir documento</option><option value="SHOW_GUIDANCE">Exibir orientação</option></select><input placeholder="Código alvo opcional" value={action.targetKey} onChange={(event) => setAction({ ...action, targetKey: event.target.value })} /><button type="submit">Adicionar ação</button></form></div>}{tab === 'documents' && <div><h3>Exigências documentais</h3><form className="builder-inline" onSubmit={addDocument}><input placeholder="CÓDIGO_DOCUMENTO" value={newDocument.documentCode} onChange={(event) => setNewDocument({ ...newDocument, documentCode: event.target.value.toUpperCase() })} required /><input placeholder="Nome do documento" value={newDocument.name} onChange={(event) => setNewDocument({ ...newDocument, name: event.target.value })} required /><select value={newDocument.requirementType} onChange={(event) => setNewDocument({ ...newDocument, requirementType: event.target.value })}><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="CONDITIONAL">Condicional</option><option value="MANUAL_REVIEW">Análise manual</option></select><button type="submit">Adicionar exigência</button></form>{editor.documents.length === 0 ? <p className="auth-muted">Nenhuma exigência configurada.</p> : editor.documents.map((item) => <div className="builder-row" key={String(item.id)}><strong>{String(item.name)}</strong><small>{String(item.requirement_type)}</small></div>)}</div>}{tab === 'external' && <div><h3>Consultas externas</h3><p className="auth-muted">Apenas a configuração do adaptador é persistida nesta fase; nenhuma API externa real é chamada.</p><form className="builder-inline" onSubmit={addQuery}><select value={newQuery.sourceId} onChange={(event) => setNewQuery({ ...newQuery, sourceId: event.target.value })} required><option value="">Fonte autorizada</option>{dataSources.map((source) => <option key={String(source.id)} value={String(source.id)}>{String(source.name)} · {String(source.status)}</option>)}</select><input placeholder="CONSULTA_VEICULO" value={newQuery.queryKey} onChange={(event) => setNewQuery({ ...newQuery, queryKey: event.target.value.toUpperCase() })} required /><input placeholder="Nome da consulta" value={newQuery.label} onChange={(event) => setNewQuery({ ...newQuery, label: event.target.value })} required /><input placeholder="Contexto" value={newQuery.contextKey} onChange={(event) => setNewQuery({ ...newQuery, contextKey: event.target.value })} required /><button type="submit">Adicionar consulta</button></form>{editor.queries.length === 0 ? <p className="auth-muted">Nenhuma consulta configurada.</p> : editor.queries.map((item) => <div className="builder-row" key={String(item.id)}><strong>{String(item.label)}</strong><small>{String(item.query_key)} · {String(item.status || 'configurada')}</small></div>)}<form className="builder-inline" onSubmit={addMapping}><select value={mapping.queryId} onChange={(event) => setMapping({ ...mapping, queryId: event.target.value })}><option value="">Consulta alvo</option>{editor.queries.map((item) => <option key={String(item.id)} value={String(item.id)}>{String(item.label)}</option>)}</select><select value={mapping.targetFieldKey} onChange={(event) => setMapping({ ...mapping, targetFieldKey: event.target.value })}><option value="">Campo destino</option>{editor.fields.map((field) => <option key={String(field.id)} value={String(field.field_key)}>{String(field.label)}</option>)}</select><input placeholder="Caminho normalizado" value={mapping.normalizedPath} onChange={(event) => setMapping({ ...mapping, normalizedPath: event.target.value })} required /><button type="submit">Adicionar mapeamento</button></form></div>}{tab === 'messages' && <div><h3>Mensagens configuráveis</h3><form className="builder-inline" onSubmit={addMessage}><input placeholder="CHAVE_DA_MENSAGEM" value={newMessage.messageKey} onChange={(event) => setNewMessage({ ...newMessage, messageKey: event.target.value.toUpperCase() })} required /><select value={newMessage.severity} onChange={(event) => setNewMessage({ ...newMessage, severity: event.target.value })}><option value="INFO">Informação</option><option value="WARNING">Atenção</option><option value="ERROR">Erro</option><option value="SUCCESS">Sucesso</option></select><input placeholder="Texto exibido ao usuário" value={newMessage.content} onChange={(event) => setNewMessage({ ...newMessage, content: event.target.value })} required /><button type="submit">Adicionar mensagem</button></form>{editor.messages.map((item) => <div className="builder-row" key={String(item.id)}><strong>{String(item.message_key)}</strong><small>{String(item.severity)} · {String(item.content)}</small></div>)}</div>}{tab === 'simulate' && String(editor.version.code) === 'LOWERED_SUSPENSION' ? <SuspensionForm apiBase="/api/admin/suspension" /> : tab === 'simulate' && String(editor.version.code) === 'ENGINE_REGISTRATION' ? <MotorForm apiBase="/api/admin/motor" /> : tab === 'simulate' && <div><h3>Simulador da versão em rascunho</h3><p className="auth-muted">Use dados fictícios. O avaliador é o mesmo motor declarativo previsto para o fluxo operacional.</p><form className="builder-simulator" onSubmit={simulate}>{editor.fields.filter((field) => field.field_type !== 'CALCULATED' && !(String(answers['engine.identification_mode'] || '').toUpperCase() === 'MANUAL' && String(field.field_key) === 'vehicle_donor.plate')).map(renderField)}<button className="auth-button" type="submit">Executar simulação</button></form>{simulation && <ServiceResultView serviceName={String(editor.version.service_name || 'Serviço Doc Motor')} simulation={simulation} fields={editor.fields as Array<Record<string, unknown>>} />}</div>}</div></>}</section>
}

function AdminDashboard({ user }: { user: User }) {
  const [summary, setSummary] = useState<AdminSummary | null>(null); const [error, setError] = useState('')
  useEffect(() => { api('/api/admin/summary').then((result) => setSummary(result as AdminSummary)).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar o resumo administrativo.')) }, [])
  return <DashboardFrame user={user} title="PAINEL ADMINISTRATIVO"><p className="auth-muted">Indicadores e aprovações persistidos no MySQL.</p>{error && <Message error={error} />}<div className="metric-grid"><Metric label="Usuários" value={summary?.users?.total_users ?? '—'} /><Metric label="Clientes" value={summary?.users?.total_clients ?? '—'} /><Metric label="Parceiros" value={summary?.partners?.total_partners ?? '—'} /><Metric label="Aguardando aprovação" value={summary?.partners?.pending_partners ?? '—'} /><Metric label="Aprovados" value={summary?.partners?.active_partners ?? '—'} /><Metric label="Recusados" value={summary?.partners?.rejected_partners ?? '—'} /><Metric label="Suspensos" value={summary?.partners?.suspended_partners ?? '—'} /></div><div className="dashboard-notice"><strong>Central administrativa</strong><br />Use a navegação lateral para revisar parceiros, clientes, serviços e configurações. A aprovação altera empresa e usuários vinculados em uma única transação.</div></DashboardFrame>
}

function AdminPartnersPage({ user }: { user: User }) {
  const [items, setItems] = useState<Array<Record<string, string>>>([]); const [pendingItems, setPendingItems] = useState<Array<Record<string, string>>>([]); const [status, setStatus] = useState('ACTIVE'); const [query, setQuery] = useState(''); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [activeTotal, setActiveTotal] = useState(0); const [pendingTotal, setPendingTotal] = useState(0); const [selected, setSelected] = useState<ApiResult | null>(null); const [error, setError] = useState('')
  const load = () => { const params = new URLSearchParams({ status, page: String(page), pageSize: '20' }); if (query.trim()) params.set('q', query.trim()); return Promise.all([api(`/api/admin/partners?${params.toString()}`), api(`/api/admin/partners?status=PENDING&page=1&pageSize=20${query.trim() ? `&q=${encodeURIComponent(query.trim())}` : ''}`), api(`/api/admin/partners?status=ACTIVE&page=1&pageSize=1${query.trim() ? `&q=${encodeURIComponent(query.trim())}` : ''}`)]).then(([result, pending, active]) => { setItems((result.items as Array<Record<string, string>>) || []); setTotal(Number(result.total || 0)); setPendingItems((pending.items as Array<Record<string, string>>) || []); setPendingTotal(Number(pending.total || 0)); setActiveTotal(Number(active.total || 0)) }).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar os parceiros.')) }
  useEffect(() => { void load() }, [status, query, page])
  const changeStatus = async (id: string, nextStatus: string) => { const reason = nextStatus === 'REJECTED' || nextStatus === 'SUSPENDED' ? window.prompt('Motivo (opcional):') || '' : ''; try { await api(`/api/admin/partners/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status: nextStatus, reason }) }); await load() } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível atualizar o parceiro.') } }
  const showDetails = async (id: string) => { try { setSelected(await api(`/api/admin/partners/${id}/details`)) } catch (err) { setError(err instanceof Error ? err.message : 'Não foi possível carregar os detalhes.') } }
  const partnerRows = (list: Array<Record<string, string>>) => <div className="admin-table">{list.length === 0 ? <p className="auth-muted">Nenhum parceiro neste filtro.</p> : list.map((partner) => <article className="admin-row" key={partner.id}><div><strong>{partner.trade_name || partner.legal_name}</strong><span>{partner.responsible_name} · {partner.email}</span><span>{partner.segment} · {partner.city || '—'}/{partner.state || '—'} · {translateStatus(partner.status)}</span></div><div className="admin-actions"><button onClick={() => void showDetails(partner.id)}>Detalhes</button>{partner.status === 'PENDING' && <><button onClick={() => void changeStatus(partner.id, 'ACTIVE')}>Aprovar</button><button onClick={() => void changeStatus(partner.id, 'REJECTED')}>Recusar</button></>}{partner.status === 'ACTIVE' && <button onClick={() => void changeStatus(partner.id, 'SUSPENDED')}>Suspender</button>}{partner.status === 'SUSPENDED' && <button onClick={() => void changeStatus(partner.id, 'ACTIVE')}>Reativar</button>}</div></article>)}</div>
  return <DashboardFrame user={user} title="PARCEIROS"><div className="admin-toolbar"><h2>Gestão de parceiros</h2><select aria-label="Filtrar por status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1) }}><option value="ACTIVE">Ativos</option><option value="PENDING">Pendentes</option><option value="SUSPENDED">Suspensos</option><option value="REJECTED">Recusados</option></select></div><div className="metric-grid partner-counts"><Metric label="Ativos" value={activeTotal} /><Metric label="Pendentes" value={pendingTotal} /></div>{pendingTotal > 0 && status !== 'PENDING' && <section className="partner-pending-section"><h2>Solicitações pendentes</h2><p className="auth-muted">Revise estas solicitações independentemente do filtro principal.</p>{partnerRows(pendingItems)}</section>}<div className="admin-filters"><input aria-label="Pesquisar parceiros" placeholder="Nome, empresa, documento ou e-mail" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1) }} /></div>{error && <Message error={error} />}{partnerRows(items)}{total > 20 && <div className="admin-pagination"><button disabled={page <= 1} onClick={() => setPage((current) => current - 1)}>Anterior</button><span>Página {page} · {total} registros</span><button disabled={page * 20 >= total} onClick={() => setPage((current) => current + 1)}>Próxima</button></div>}{selected && <><AdminPartnerDetails data={selected} onClose={() => setSelected(null)} /><AdminPartnerEditForm data={selected} /></>}</DashboardFrame>
}

function AdminPartnerDetails({ data, onClose }: { data: ApiResult; onClose: () => void }) { const company = data.company as Record<string, string>; const members = (data.members as Array<Record<string, string>>) || []; const history = (data.history as Array<Record<string, string>>) || []; const [tab, setTab] = useState('cadastral'); const [form, setForm] = useState({ scope: 'INHERIT', model: 'NONE', percentage: '', fixedAmountCents: '', honorariumOnly: false }); const [message, setMessage] = useState(''); useEffect(() => { void api(`/api/admin/partners/${company.id}/commission`).then((result) => { const override = (result.override || {}) as Record<string, unknown>; setForm({ scope: override.model ? (override.model === 'NONE' ? 'DISABLED' : 'CUSTOM') : 'INHERIT', model: String(override.model || 'NONE'), percentage: override.percentage == null ? '' : String(override.percentage), fixedAmountCents: override.fixed_amount_cents == null ? '' : String(Number(override.fixed_amount_cents) / 100), honorariumOnly: Boolean(override.honorarium_only) }) }).catch((err) => setMessage(err instanceof Error ? err.message : 'Não foi possível carregar a comissão.')) }, [company.id]); const saveCommission = async (event: FormEvent) => { event.preventDefault(); try { await api(`/api/admin/partners/${company.id}/commission`, { method: 'PUT', body: JSON.stringify({ scope: form.scope, model: form.model, percentage: form.percentage === '' ? null : Number(form.percentage), fixedAmountCents: form.fixedAmountCents === '' ? null : Math.round(Number(form.fixedAmountCents.replace(',', '.')) * 100), honorariumOnly: form.honorariumOnly }) }); setMessage(form.scope === 'INHERIT' ? 'Parceiro voltou a herdar a regra global.' : 'Regra individual salva.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível salvar o override.') } }; return <div className="dashboard-notice"><button className="auth-button auth-secondary" onClick={onClose}>Fechar detalhes</button><h2>{company.trade_name || company.legal_name}</h2><p>{company.responsible_name} · {company.email} · {company.whatsapp}</p><p>{company.cpf_cnpj} · {company.segment} · {company.city || '—'}/{company.state || '—'}</p><div className="detail-tabs" role="tablist" aria-label="Detalhes do parceiro">{[['cadastral', 'Cadastral'], ['members', 'Colaboradores'], ['commission', 'Comissão'], ['history', 'Histórico']].map(([value, label]) => <button type="button" role="tab" aria-selected={tab === value} className={tab === value ? 'is-active' : ''} key={value} onClick={() => setTab(value)}>{label}</button>)}</div>{tab === 'cadastral' && <section><h3>Dados cadastrais</h3><p>Documento: {company.cpf_cnpj || '—'} · Segmento: {company.segment || '—'}</p><p>Localidade: {company.city || '—'}/{company.state || '—'}</p><AdminPartnerEditForm data={data} /></section>}{tab === 'members' && <section><h3>Usuários vinculados</h3>{members.length === 0 ? <p>Sem colaboradores vinculados.</p> : members.map((member) => <p key={member.id}>{member.name} · {member.email} · {translateStatus(member.status)}</p>)}</section>}{tab === 'commission' && <section><h3>Comissão individual</h3><form className="auth-grid" onSubmit={saveCommission}><label className="auth-field"><span>Aplicação</span><select aria-label="Aplicação da comissão" value={form.scope} onChange={(event) => setForm({ ...form, scope: event.target.value })}><option value="INHERIT">Herdar regra global</option><option value="CUSTOM">Regra personalizada</option><option value="DISABLED">Desativar para este parceiro</option></select></label>{form.scope === 'CUSTOM' && <><label className="auth-field"><span>Modelo</span><select aria-label="Modelo individual" value={form.model} onChange={(event) => setForm({ ...form, model: event.target.value })}><option value="SERVICE_PERCENTAGE">Percentual dos serviços</option><option value="HONORARIUM_PERCENTAGE">Percentual dos honorários</option><option value="FULL_HONORARIUM">Honorário integral</option><option value="FIXED_AMOUNT">Valor fixo</option></select></label>{form.model.includes('PERCENTAGE') && <Field label="Percentual (%)" name="percentage" required value={form.percentage} onChange={(value) => setForm({ ...form, percentage: value })} />}{form.model === 'FIXED_AMOUNT' && <Field label="Valor fixo (R$)" name="fixedAmount" required value={form.fixedAmountCents} onChange={(value) => setForm({ ...form, fixedAmountCents: value })} />}</>}{form.scope === 'CUSTOM' && form.model === 'HONORARIUM_PERCENTAGE' && <label className="auth-consent"><span><input type="checkbox" checked={form.honorariumOnly} onChange={(event) => setForm({ ...form, honorariumOnly: event.target.checked })} /> Somente honorários</span></label>}<button className="auth-button" type="submit">Salvar regra</button></form>{message && <p className="auth-muted">{message}</p>}</section>}{tab === 'history' && <section><h3>Histórico de alterações</h3>{history.length === 0 ? <p>Sem alterações registradas.</p> : history.map((item, index) => <p key={`${item.created_at}-${index}`}>{item.created_at} · {item.action}</p>)}</section>}</div> }

function AdminPartnerEditForm({ data }: { data: ApiResult }) { const company = data.company as Record<string, string>; const [form, setForm] = useState({ legalName: company.legal_name || '', tradeName: company.trade_name || '', responsibleName: company.responsible_name || '', email: company.email || '', whatsapp: company.whatsapp || '', segment: company.segment || '', city: company.city || '', state: company.state || '' }); const [message, setMessage] = useState(''); const save = async (event: FormEvent) => { event.preventDefault(); try { await api(`/api/admin/partners/${company.id}`, { method: 'PATCH', body: JSON.stringify(form) }); setMessage('Dados do parceiro atualizados.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível atualizar o parceiro.') } }; return <div className="dashboard-notice"><h3>Editar cadastro</h3><form className="auth-grid" onSubmit={save}><Field label="Razão social / nome" name="legalName" value={form.legalName} onChange={(value) => setForm({ ...form, legalName: value })} /><Field label="Nome fantasia" name="tradeName" required={false} value={form.tradeName} onChange={(value) => setForm({ ...form, tradeName: value })} /><Field label="Responsável" name="responsibleName" value={form.responsibleName} onChange={(value) => setForm({ ...form, responsibleName: value })} /><Field label="E-mail" name="email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} /><Field label="WhatsApp" name="whatsapp" value={form.whatsapp} onChange={(value) => setForm({ ...form, whatsapp: value })} /><Field label="Segmento" name="segment" value={form.segment} onChange={(value) => setForm({ ...form, segment: value })} /><Field label="Cidade" name="city" required={false} value={form.city} onChange={(value) => setForm({ ...form, city: value })} /><Field label="UF" name="state" required={false} value={form.state} onChange={(value) => setForm({ ...form, state: value.toUpperCase() })} /><button className="auth-button" type="submit">Salvar cadastro</button></form>{message && <p className="auth-muted">{message}</p>}</div> }

function AdminUsersPage({ user }: { user: User }) { const [items, setItems] = useState<Array<Record<string, string>>>([]); const [query, setQuery] = useState(''); const [status, setStatus] = useState(''); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); useEffect(() => { const params = new URLSearchParams({ role: 'CLIENT', page: String(page), pageSize: '20' }); if (query.trim()) params.set('q', query.trim()); if (status) params.set('status', status); void api(`/api/admin/users?${params.toString()}`).then((result) => { setItems((result.items as Array<Record<string, string>>) || []); setTotal(Number(result.total || 0)) }) }, [query, status, page]); return <DashboardFrame user={user} title="CLIENTES"><p className="auth-muted">Clientes cadastrados no banco de dados.</p><div className="admin-filters"><input aria-label="Pesquisar clientes" placeholder="Nome ou e-mail" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1) }} /><select aria-label="Filtrar clientes por status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1) }}><option value="">Todos os status</option><option value="ACTIVE">Ativos</option><option value="SUSPENDED">Suspensos</option><option value="DISABLED">Desativados</option></select></div><div className="admin-table">{items.length === 0 ? <p className="auth-muted">Nenhum cliente encontrado.</p> : items.map((item) => <article className="admin-row" key={item.id}><div><strong>{item.name}</strong><span>{item.email} · {item.whatsapp || 'WhatsApp não informado'}</span></div><span>{translateStatus(item.status)}</span></article>)}</div>{total > 20 && <div className="admin-pagination"><button disabled={page <= 1} onClick={() => setPage((current) => current - 1)}>Anterior</button><span>Página {page} · {total} registros</span><button disabled={page * 20 >= total} onClick={() => setPage((current) => current + 1)}>Próxima</button></div>}</DashboardFrame> }

function AdminPlaceholderPage({ user, title, text }: { user: User; title: string; text: string }) { return <DashboardFrame user={user} title={title}><div className="dashboard-notice"><strong>Disponível em preparação</strong><br />{text}</div></DashboardFrame> }

function AdminCommissionsPage({ user }: { user: User }) { const [form, setForm] = useState({ model: 'NONE', percentage: '', fixedAmountCents: '', honorariumOnly: false }); const [partners, setPartners] = useState<BuilderItem[]>([]); const [selectedPartner, setSelectedPartner] = useState(''); const [charges, setCharges] = useState([{ amount: '100,00', chargeNature: 'SERVICE', isPublicFee: false }, { amount: '50,00', chargeNature: 'HONORARY', isPublicFee: false }]); const [message, setMessage] = useState('Carregando…'); const [simulation, setSimulation] = useState<Record<string, unknown> | null>(null); useEffect(() => { void api('/api/admin/commissions').then((result) => { const settings = (result.settings || {}) as Record<string, unknown>; setForm({ model: String(settings.default_model || 'NONE'), percentage: settings.default_percentage == null ? '' : String(settings.default_percentage), fixedAmountCents: settings.default_fixed_amount_cents == null ? '' : String(Number(settings.default_fixed_amount_cents) / 100), honorariumOnly: Boolean(settings.honorarium_only) }); setMessage(result.migrationRequired ? 'A migration 004 ainda não foi importada no banco.' : '') }).catch((err) => setMessage(err instanceof Error ? err.message : 'Não foi possível carregar a configuração.')) }, []); useEffect(() => { void api<{ items?: BuilderItem[] }>('/api/admin/partners?status=ACTIVE&pageSize=100').then((result) => setPartners(result.items || [])).catch(() => undefined) }, []); const configPayload = () => ({ model: form.model, percentage: form.model.includes('PERCENTAGE') ? Number(form.percentage) : null, fixedAmountCents: form.model === 'FIXED_AMOUNT' ? Math.round(Number(form.fixedAmountCents.replace(',', '.')) * 100) : null, honorariumOnly: form.honorariumOnly }); const save = async (event: FormEvent) => { event.preventDefault(); setMessage(''); try { await api('/api/admin/commissions', { method: 'PUT', body: JSON.stringify(configPayload()) }); setMessage('Configuração global salva.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível salvar a configuração.') } }; const simulate = async (event: FormEvent) => { event.preventDefault(); setMessage(''); try { const result = await api<{ result?: Record<string, unknown> }>('/api/admin/commissions/simulate', { method: 'POST', body: JSON.stringify({ ...configPayload(), partnerCompanyId: selectedPartner || undefined, charges: charges.map((charge) => ({ amountCents: Math.round(Number(charge.amount.replace(',', '.')) * 100), chargeNature: charge.chargeNature, isPublicFee: charge.isPublicFee })) }) }); setSimulation(result.result || null); setMessage('Simulação calculada pelo backend. Nenhum registro financeiro foi criado.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível simular a comissão.') } }; const needsPercentage = form.model.includes('PERCENTAGE'); const money = (value: unknown) => `R$ ${(Number(value || 0) / 100).toFixed(2).replace('.', ',')}`; return <DashboardFrame user={user} title="COMISSÕES"><p className="auth-muted">Defina a regra global e teste cenários com cobranças fictícias. A simulação não grava orçamento, comissão ou pagamento.</p>{message && <p className="auth-muted">{message}</p>}<form className="auth-grid" onSubmit={save}><label className="auth-field"><span>Modelo global</span><select value={form.model} onChange={(event) => setForm({ ...form, model: event.target.value })}><option value="NONE">Sem comissão</option><option value="SERVICE_PERCENTAGE">Percentual dos serviços</option><option value="HONORARIUM_PERCENTAGE">Percentual dos honorários</option><option value="FULL_HONORARIUM">Honorário integral</option><option value="FIXED_AMOUNT">Valor fixo</option></select></label>{needsPercentage && <Field label="Percentual (%)" name="percentage" required value={form.percentage} onChange={(value) => setForm({ ...form, percentage: value })} />}{form.model === 'FIXED_AMOUNT' && <Field label="Valor fixo (R$)" name="fixedAmount" required value={form.fixedAmountCents} onChange={(value) => setForm({ ...form, fixedAmountCents: value })} />} {form.model === 'HONORARIUM_PERCENTAGE' && <label className="auth-consent"><span><input type="checkbox" checked={form.honorariumOnly} onChange={(event) => setForm({ ...form, honorariumOnly: event.target.checked })} /> Usar apenas cobranças de honorários</span></label>}<button className="auth-button" type="submit">Salvar configuração global</button></form><section className="commission-simulator"><h2>Simulador de comissão</h2><p className="auth-muted">Use valores ilustrativos em reais. O cálculo considera a regra efetiva global ou individual e exclui taxas públicas da base elegível.</p><label className="auth-field"><span>Parceiro (opcional)</span><select value={selectedPartner} onChange={(event) => setSelectedPartner(event.target.value)}><option value="">Usar regra global</option>{partners.map((partner) => <option key={String(partner.id)} value={String(partner.id)}>{String(partner.trade_name || partner.legal_name)}</option>)}</select></label>{charges.map((charge, index) => <div className="builder-inline" key={index}><Field label={`Cobrança ${index + 1} (R$)`} name={`charge-${index}`} required value={charge.amount} onChange={(value) => setCharges((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, amount: value } : item))} /><select aria-label={`Natureza da cobrança ${index + 1}`} value={charge.chargeNature} onChange={(event) => setCharges((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, chargeNature: event.target.value } : item))}><option value="SERVICE">Serviço</option><option value="HONORARY">Honorário</option></select><label><input type="checkbox" checked={charge.isPublicFee} onChange={(event) => setCharges((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, isPublicFee: event.target.checked } : item))} /> Taxa pública</label></div>)}<button className="auth-button" type="button" onClick={() => setCharges((current) => [...current, { amount: '0,00', chargeNature: 'SERVICE', isPublicFee: false }])}>Adicionar cobrança</button><button className="auth-button" type="button" onClick={(event) => void simulate(event as unknown as FormEvent)}>Calcular simulação</button>{simulation && <div className="dashboard-notice"><strong>Resultado da simulação</strong><br />Total: {money(simulation.totalCents)}<br />Base de serviços elegível: {money(simulation.eligibleServiceCents)}<br />Honorários elegíveis: {money(simulation.eligibleHonorariumCents)}<br />Comissão calculada: {money(simulation.commissionCents)}</div>}</section></DashboardFrame> }

function AdminSettingsPage({ user }: { user: User }) { const [form, setForm] = useState({ companyName: '', supportWhatsapp: '', supportEmail: '', city: '', state: '', privacyUrl: '', termsUrl: '' }); const [runtime, setRuntime] = useState<ApiResult | null>(null); const [message, setMessage] = useState('Carregando…'); useEffect(() => { void api('/api/admin/settings').then((result) => { const settings = (result.settings || {}) as Record<string, unknown>; setForm({ companyName: String(settings.company_name || 'Doc Motor'), supportWhatsapp: String(settings.support_whatsapp || ''), supportEmail: String(settings.support_email || ''), city: String(settings.city || ''), state: String(settings.state || ''), privacyUrl: String(settings.privacy_url || ''), termsUrl: String(settings.terms_url || '') }); setRuntime((result.runtime || {}) as ApiResult); setMessage(result.migrationRequired ? 'A Migration 005 ainda precisa ser importada pelo phpMyAdmin.' : '') }).catch((err) => setMessage(err instanceof Error ? err.message : 'Não foi possível carregar as configurações.')) }, []); const save = async (event: FormEvent) => { event.preventDefault(); try { await api('/api/admin/settings', { method: 'PUT', body: JSON.stringify(form) }); setMessage('Configurações gerais salvas.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível salvar as configurações.') } }; return <DashboardFrame user={user} title="CONFIGURAÇÕES GERAIS"><p className="auth-muted">Dados comerciais persistidos no MySQL. Credenciais, ambiente e infraestrutura permanecem somente leitura.</p>{message && <p className="auth-muted">{message}</p>}<form className="auth-grid" onSubmit={save}><Field label="Nome comercial" name="companyName" value={form.companyName} onChange={(value) => setForm({ ...form, companyName: value })} /><Field label="WhatsApp de suporte" name="supportWhatsapp" required={false} value={form.supportWhatsapp} onChange={(value) => setForm({ ...form, supportWhatsapp: value })} /><Field label="E-mail de suporte" name="supportEmail" type="email" required={false} value={form.supportEmail} onChange={(value) => setForm({ ...form, supportEmail: value })} /><Field label="Cidade" name="city" required={false} value={form.city} onChange={(value) => setForm({ ...form, city: value })} /><Field label="UF" name="state" required={false} value={form.state} onChange={(value) => setForm({ ...form, state: value.toUpperCase() })} /><Field label="URL da política de privacidade" name="privacyUrl" required={false} value={form.privacyUrl} onChange={(value) => setForm({ ...form, privacyUrl: value })} /><Field label="URL dos termos de uso" name="termsUrl" required={false} value={form.termsUrl} onChange={(value) => setForm({ ...form, termsUrl: value })} /><button className="auth-button" type="submit">Salvar configurações</button></form><div className="dashboard-notice"><strong>Informações técnicas — somente leitura</strong><br />Ambiente: {String(runtime?.appEnv || '—')}<br />Versão: {String(runtime?.version || '—')}<br />Indexação permitida: {runtime?.allowIndexing ? 'Sim' : 'Não'}</div></DashboardFrame> }

function AdminApiKeysPage({ user }: { user: User }) { const [items, setItems] = useState<Array<Record<string, unknown>>>([]); useEffect(() => { void api('/api/admin/api-keys').then((result) => setItems((result.integrations as Array<Record<string, unknown>>) || [])) }, []); return <DashboardFrame user={user} title="CHAVES DE API"><p className="auth-muted">Somente metadados seguros. Os valores permanecem exclusivamente nas variáveis privadas do backend.</p><div className="admin-table">{items.map((item) => <article className="admin-row" key={String(item.code)}><div><strong>{String(item.name)}</strong><span>Variável: {String(item.secretName)}</span><span>Chamadas reais habilitadas: {item.realCallsEnabled ? 'Sim' : 'Não'}</span></div><span>{item.configured ? 'Configurada' : 'Não configurada'}</span></article>)}</div></DashboardFrame> }

function AdminManualSettingsPage({ user }: { user: User }) {
  const [form, setForm] = useState({ companyName: '', supportWhatsapp: '', supportEmail: '', city: '', state: '', privacyUrl: '', termsUrl: '', manualWhatsapp: '', manualTeamName: '', manualMessageTemplate: '' })
  const [runtime, setRuntime] = useState<ApiResult | null>(null)
  const [message, setMessage] = useState('Carregando…')
  useEffect(() => { void api('/api/admin/settings').then((result) => { const settings = (result.settings || {}) as Record<string, unknown>; setForm({ companyName: String(settings.company_name || 'Doc Motor'), supportWhatsapp: String(settings.support_whatsapp || ''), supportEmail: String(settings.support_email || ''), city: String(settings.city || ''), state: String(settings.state || ''), privacyUrl: String(settings.privacy_url || ''), termsUrl: String(settings.terms_url || ''), manualWhatsapp: String(settings.manual_whatsapp || ''), manualTeamName: String(settings.manual_team_name || ''), manualMessageTemplate: String(settings.manual_message_template || '') }); setRuntime((result.runtime || {}) as ApiResult); setMessage(result.migrationRequired ? 'A Migration 005 ainda precisa ser importada pelo phpMyAdmin.' : '') }).catch((err) => setMessage(err instanceof Error ? err.message : 'Não foi possível carregar as configurações.')) }, [])
  const save = async (event: FormEvent) => { event.preventDefault(); try { await api('/api/admin/settings', { method: 'PUT', body: JSON.stringify(form) }); setMessage('Configurações gerais salvas.') } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível salvar as configurações.') } }
  return <DashboardFrame user={user} title="CONFIGURAÇÕES GERAIS"><p className="auth-muted">Dados comerciais e contato da análise manual persistidos no MySQL.</p>{message && <p className="auth-muted">{message}</p>}<form className="auth-grid" onSubmit={save}><Field label="Nome comercial" name="companyName" value={form.companyName} onChange={(value) => setForm({ ...form, companyName: value })} /><Field label="WhatsApp de suporte" name="supportWhatsapp" required={false} value={form.supportWhatsapp} onChange={(value) => setForm({ ...form, supportWhatsapp: value })} /><Field label="WhatsApp da análise manual" name="manualWhatsapp" required={false} value={form.manualWhatsapp} onChange={(value) => setForm({ ...form, manualWhatsapp: value })} /><Field label="Nome da equipe manual" name="manualTeamName" required={false} value={form.manualTeamName} onChange={(value) => setForm({ ...form, manualTeamName: value })} /><label className="auth-field"><span>Mensagem padrão da análise manual</span><textarea name="manualMessageTemplate" value={form.manualMessageTemplate} onChange={(event) => setForm({ ...form, manualMessageTemplate: event.target.value })} rows={4} /></label><Field label="E-mail de suporte" name="supportEmail" type="email" required={false} value={form.supportEmail} onChange={(value) => setForm({ ...form, supportEmail: value })} /><Field label="Cidade" name="city" required={false} value={form.city} onChange={(value) => setForm({ ...form, city: value })} /><Field label="UF" name="state" required={false} value={form.state} onChange={(value) => setForm({ ...form, state: value.toUpperCase() })} /><Field label="URL da política de privacidade" name="privacyUrl" required={false} value={form.privacyUrl} onChange={(value) => setForm({ ...form, privacyUrl: value })} /><Field label="URL dos termos de uso" name="termsUrl" required={false} value={form.termsUrl} onChange={(value) => setForm({ ...form, termsUrl: value })} /><button className="auth-button" type="submit">Salvar configurações</button></form><div className="dashboard-notice"><strong>Informações técnicas — somente leitura</strong><br />Ambiente: {String(runtime?.appEnv || '—')}<br />Versão: {String(runtime?.version || '—')}<br />Indexação permitida: {runtime?.allowIndexing ? 'Sim' : 'Não'}</div></DashboardFrame>
}

function Metric({ label, value }: { label: string; value: string | number }) { return <div className="metric"><span>{label}</span><strong>{value}</strong></div> }

function CollaboratorForm({ onCreated }: { onCreated: () => void }) { const [form, setForm] = useState({ name: '', email: '', whatsapp: '', password: '', passwordConfirmation: '' }); const [message, setMessage] = useState(''); const submit = async (event: FormEvent) => { event.preventDefault(); setMessage(''); try { await api('/api/partner/members', { method: 'POST', body: JSON.stringify(form) }); setForm({ name: '', email: '', whatsapp: '', password: '', passwordConfirmation: '' }); setMessage('Colaborador adicionado.'); onCreated() } catch (err) { setMessage(err instanceof Error ? err.message : 'Não foi possível adicionar o colaborador.') } }; return <details className="password-change"><summary>Adicionar colaborador</summary><form onSubmit={submit}><Field label="Nome" name="name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} /><Field label="E-mail" name="email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} /><Field label="WhatsApp" name="whatsapp" required={false} value={form.whatsapp} onChange={(value) => setForm({ ...form, whatsapp: value })} /><PasswordHint role="PARTNER" /><Field label="Senha provisória" name="password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} /><Field label="Confirme a senha" name="passwordConfirmation" type="password" value={form.passwordConfirmation} onChange={(value) => setForm({ ...form, passwordConfirmation: value })} /><button className="auth-button" type="submit">Adicionar colaborador</button>{message && <p className="auth-muted">{message}</p>}</form></details> }

function PartnerDashboard({ user }: { user: User }) { const [company, setCompany] = useState<Record<string, string> | null>(null); const [members, setMembers] = useState<Array<Record<string, string>>>([]); const [error, setError] = useState(''); const loadMembers = () => api('/api/partner/members').then((result) => setMembers((result as ApiResult & { items?: Array<Record<string, string>> }).items || [])).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar os colaboradores.')); useEffect(() => { Promise.all([api('/api/partner/dashboard'), api('/api/partner/members')]).then(([companyResult, membersResult]) => { setCompany((companyResult as ApiResult & { company?: Record<string, string> }).company || null); setMembers((membersResult as ApiResult & { items?: Array<Record<string, string>> }).items || []) }).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar o painel.')) }, []); return <DashboardFrame user={user} title="VISÃO GERAL"><p className="auth-muted">Resumo operacional da parceria</p>{error && <Message error={error} />}<div className="dashboard-card-grid"><div className="dashboard-notice"><span className="dashboard-label">EMPRESA</span><strong>{company?.trade_name || company?.legal_name || 'Carregando…'}</strong><br />{company?.segment || 'Segmento não informado'} · {company?.city || 'Cidade não informada'}/{company?.state || '—'}<br /><span>Status: {translateStatus(company?.status)}</span></div><div className="dashboard-notice dashboard-notice-blue"><span className="dashboard-label">ACESSO</span><strong>{company?.company_role === 'OWNER' ? 'Responsável principal' : 'Colaborador'}</strong><br />Serviços configurados ficam disponíveis conforme aprovação e permissões.</div></div><h2>Colaboradores</h2><div className="admin-table">{members.map((member) => <article className="admin-row" key={member.id}><div><strong>{member.name}</strong><span>{member.email} · {member.company_role}</span></div><span>{translateStatus(member.status)}</span></article>)}</div>{company?.company_role === 'OWNER' && <CollaboratorForm onCreated={loadMembers} />}<p className="auth-muted dashboard-disabled">Orçamentos, clientes, documentos e financeiro serão liberados em fases futuras.</p></DashboardFrame> }

function ClientDashboard({ user }: { user: User }) { return <DashboardFrame user={user} title="PAINEL DO CLIENTE"><div className="dashboard-notice"><strong>Meus dados</strong><br />{user.email}<br />{translateStatus(user.status)}</div><p className="auth-muted dashboard-disabled">Veículos, orçamentos, serviços, documentos e acompanhamento serão adicionados em fases futuras.</p></DashboardFrame> }

function AccountPage({ user }: { user: User }) { return <DashboardFrame user={user} title="MINHA CONTA"><div className="dashboard-notice"><strong>{user.name}</strong><br />{user.email}<br />Perfil: {user.role === 'ADMINISTRATOR' ? 'Administrador' : user.role === 'PARTNER' ? 'Parceiro' : 'Cliente'}</div><ChangePasswordForm role={user.role} /></DashboardFrame> }

function OperationalServicePage({ user, title, serviceCode, apiBase = '/api/admin', description, available = true }: { user: User; title: string; serviceCode?: string; apiBase?: string; description: string; available?: boolean }) {
  return <DashboardFrame user={user} title={title.toUpperCase()}>{available && serviceCode ? <DeclarativeSimulationPage serviceCode={serviceCode} title={title} apiBase={apiBase} /> : <div className="dashboard-notice"><strong>Funcionalidade em desenvolvimento</strong><br />{description}<br /><small>Esta página já faz parte da estrutura operacional, mas não executa chamadas externas nem cria documentos oficiais.</small></div>}</DashboardFrame>
}

function MotorOperationalPage({ user, apiBase = '/api/admin/motor' }: { user: User; apiBase?: '/api/admin/motor' | '/api/partner/motor' }) {
  return <DashboardFrame user={user} title="REGULARIZAÇÃO DE MOTOR"><MotorForm apiBase={apiBase} /></DashboardFrame>
}

function SuspensionOperationalPage({ user, apiBase = '/api/admin/suspension' }: { user: User; apiBase?: '/api/admin/suspension' | '/api/partner/suspension' }) {
  return <DashboardFrame user={user} title="REGULARIZAÇÃO DE SUSPENSÃO"><SuspensionForm apiBase={apiBase} /></DashboardFrame>
}

export function DashboardPage({ role }: { role: 'ADMINISTRATOR' | 'PARTNER' | 'CLIENT' }) {
  const [user, setUser] = useState<User | null>(null); const [error, setError] = useState('')
  useEffect(() => { api('/api/auth/me').then((result) => { if (!result.user || result.user.role !== role) window.location.assign('/acesso-nao-autorizado'); else setUser(result.user) }).catch((err) => setError(err instanceof Error ? err.message : 'Não foi possível carregar seu acesso.')) }, [role])
  if (!user) return <Shell><section className="auth-card"><p className="auth-muted">{error || 'Carregando seu painel…'}</p></section></Shell>
  if (role === 'ADMINISTRATOR') {
    const path = window.location.pathname
    if (path === '/admin/minha-conta') return <AccountPage user={user} />
    if (path === '/admin/parceiros') return <AdminPartnersPage user={user} />
    if (path === '/admin/clientes') return <AdminUsersPage user={user} />
    if (path === '/admin/configuracao-servicos') return <DashboardFrame user={user} title="CONFIGURAÇÃO DE SERVIÇOS"><ServiceBuilder /></DashboardFrame>
    if (path === '/admin/simulador-declarativo') return <DashboardFrame user={user} title="CONFIGURAÇÃO DE SERVIÇOS"><ServiceBuilder /></DashboardFrame>
    if (path === '/admin/servicos/regularizacao-motor') return <MotorOperationalPage user={user} />
    if (path === '/admin/servicos/suspensao') return <SuspensionOperationalPage user={user} />
    if (path === '/admin/servicos/outras-modificacoes') return <OperationalServicePage user={user} title="Outras modificações" description="O catálogo central será utilizado nesta operação após a configuração e homologação do serviço." available={false} />
    if (path === '/admin/servicos/emissor-crlv') return <OperationalServicePage user={user} title="Emissor de CRLV" description="A emissão de CRLV está em desenvolvimento. Nenhum documento oficial é gerado nesta fase." available={false} />
    if (path === '/admin/servicos/consultas') return <OperationalServicePage user={user} title="Consultas" description="As modalidades de consulta serão adicionadas futuramente, sem chamadas externas nesta fase." available={false} />
    if (path === '/admin/catalogo-modificacoes') return <DashboardFrame user={user} title="CATÁLOGO DE MODIFICAÇÕES"><ModificationCatalogAdminPage /></DashboardFrame>
    if (path === '/admin/comissoes') return <AdminCommissionsPage user={user} />
    if (path === '/admin/servicos-solicitados') return <AdminPlaceholderPage user={user} title="SOLICITAÇÕES DE SERVIÇO" text="Nenhuma solicitação operacional é exibida nesta fase." />
    if (path === '/admin/chaves-api') return <AdminApiKeysPage user={user} />
    if (path === '/admin/configuracoes') return <AdminManualSettingsPage user={user} />
    return <AdminDashboard user={user} />
  }
  if (role === 'PARTNER') {
    const path = window.location.pathname
    if (path === '/parceiro/minha-conta') return <AccountPage user={user} />
    const servicePages: Record<string, { title: string; description: string; code?: string }> = { '/parceiro/servicos/regularizacao-motor': { title: 'Regularização de motor', code: 'ENGINE_REGISTRATION', description: 'A operação de cadastro de motor será liberada após a configuração comercial do serviço.' }, '/parceiro/servicos/suspensao': { title: 'Regularizar suspensão', code: 'LOWERED_SUSPENSION', description: 'A operação de suspensão será liberada após a homologação comercial.' }, '/parceiro/servicos/outras-modificacoes': { title: 'Outras modificações', description: 'O serviço será liberado após configuração e homologação do catálogo.' }, '/parceiro/servicos/emissor-crlv': { title: 'Emissor de CRLV', description: 'A emissão de CRLV está em desenvolvimento e não gera documentos oficiais.' }, '/parceiro/servicos/consultas': { title: 'Consultas', description: 'As consultas externas ainda não estão disponíveis.' } }
    const page = servicePages[path]
    if (path === '/parceiro/servicos/regularizacao-motor') return <MotorOperationalPage user={user} apiBase="/api/partner/motor" />
    if (path === '/parceiro/servicos/suspensao') return <SuspensionOperationalPage user={user} apiBase="/api/partner/suspension" />
    return page ? <OperationalServicePage user={user} title={page.title} serviceCode={page.code} apiBase="/api/partner" description={page.description} available={Boolean(page.code)} /> : <PartnerDashboard user={user} />
  }
  return <ClientDashboard user={user} />
}
